files.决策卡.py:
"""掌柜 · 决策卡：主人定的事 → 经营决策库里一张合格式的卡（自动取号、套模板、查重、换新版）
用法：python3 决策卡.py --类 ZC|HP|DR --标题 售价下限 --原话 "以后不做 39 块以下的" [--参数 售价下限=39 ...]
       [--内容 "…"] [--状态 生效|待确认] [--替代 D-ZC-003] [--今天 2026-10-31] [--店铺 <店铺文件夹>] [--演练]
规矩（库/模板/决策卡.md）：编号 D-<类>-<三位号>，按库里已有的最大号 +1；同标题已有一张「生效」的，要用 --替代 换新版
（同编号、版本 +1、文件名加 -v<版本>，旧卡改「已停用」不删）；参数名要和 库/默认值/看店-服装店.md 同名，脚本才用得上。
Bot 实测自报 1（10-31）：之前只写「照模板」，手写的卡缺编号、状态、版本、参数。"""
import argparse, datetime as dt, pathlib, re, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); import 底子


def main(argv=None):
    a = argparse.ArgumentParser()
    a.add_argument("--类", required=True, choices=["ZC", "HP", "DR"]); a.add_argument("--标题", required=True)
    a.add_argument("--原话", required=True); a.add_argument("--参数", nargs="*", default=[]); a.add_argument("--内容", default="")
    a.add_argument("--状态", default="生效", choices=["生效", "待确认"]); a.add_argument("--替代"); a.add_argument("--影响", default="")
    a.add_argument("--今天"); a.add_argument("--店铺"); a.add_argument("--演练", action="store_true")
    a = a.parse_args(argv)
    dp = 底子.dianpu(a.店铺)
    jc = dp / "经营决策库"
    jin = a.今天 or str(底子.jintian())
    ka = {p: 底子.kaitou(p) for p in sorted(jc.glob("D-*.md")) if not p.name.startswith("._")} if jc.exists() else {}
    cs = 底子.moren_canshu()
    can = dict(x.split("=", 1) for x in a.参数 if "=" in x)
    ti = [f"参数「{n}」默认值里没有这个名字，脚本用不上；要用请改成默认值里的名字" for n in can if n not in cs]
    if a.替代:
        jiu = [(p, k) for p, k in ka.items() if k.get("编号") == a.替代 and k.get("状态") == "生效"]
        if not jiu:
            raise SystemExit(f"找不到生效的 {a.替代}，换不了新版")
        bh, bb = a.替代, max(int(k.get("版本") or 1) for _, k in jiu) + 1
        ming = f"{bh}-{a.标题}-v{bb}.md"; tidai = f"{bh} 版本 {bb - 1}"
    else:
        tong = [k["编号"] for k in ka.values() if k.get("标题") == a.标题 and k.get("状态") == "生效"]
        if tong:
            raise SystemExit(f"已经有一张生效的「{a.标题}」（{tong[0]}）；改它就加 --替代 {tong[0]}，旧卡会改成已停用")
        hao = [int(m.group(1)) for k in ka.values() if (m := re.match(rf"D-{a.类}-(\d+)", k.get("编号", "")))]
        bh, bb = f"D-{a.类}-{max(hao, default=0) + 1:03d}", 1
        ming = f"{bh}-{a.标题}.md"; tidai = "无"
    canshu = "".join(f"\n  {n}: {v}" for n, v in can.items())
    t = f"""---
编号: {bh}
标题: {a.标题}
状态: {a.状态}
版本: {bb}
生效日期: {jin}
定的人: 主人原话「{a.原话}」
替代: {tidai}
影响: [{a.影响}]
参数:{canshu}
---

# {a.标题}
{a.内容 or a.原话}
"""
    print(t)
    for x in ti:
        print("⚠️ " + x)
    if a.演练:
        return
    jc.mkdir(parents=True, exist_ok=True)
    if a.替代:
        for p, _ in jiu:
            p.write_text(re.sub(r"^状态: 生效", "状态: 已停用", p.read_text(encoding="utf-8"), count=1, flags=re.M), encoding="utf-8")
    (jc / ming).write_text(t, encoding="utf-8")
    print(f"已写 {jc / ming}" + (f"；{a.替代} 旧版改成已停用" if a.替代 else ""))


if __name__ == "__main__":
    main()

files.回执.py:
"""云间成员回执：每次干完活往 店铺/<店>/回执/<日期>/<成员>.json 记一笔，掌柜读它出报（四位同一个写法，格式正本在掌柜 keep-base/回执格式.json）。
脚本里：import 回执; 回执.ji(店铺文件夹, "brok", zuole={"第一句": 1}, chule=["发版单 H11"], kazai=[...], deng=[...], shu={"分层": {...}}, chuchu="精选联盟·合作消息")
命令行：python3 回执.py --店铺 <文件夹> --成员 brok [--做了 第一句=1 …] [--出了 …] [--卡在 …] [--等主人定 …] [--今天 2026-11-10]
做了：同名累加；出了／卡在／等主人定：去重追加；数：同名整块换新。只记数和结论，不记联系方式、收件信息。"""
import argparse, datetime as dt, json, os, pathlib


def ji(dp, chengyuan, zuole=None, chule=(), kazai=(), deng=(), shu=None, chuchu="", jintian=None):
    if not dp:
        return None
    day = str(jintian or os.environ.get("YUNJIAN_TODAY") or dt.date.today())[:10]
    p = pathlib.Path(dp) / "回执" / day / f"{chengyuan}.json"
    p.parent.mkdir(parents=True, exist_ok=True)
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        d = {"成员": chengyuan, "店铺": pathlib.Path(dp).name, "日期": day, "做了": {}, "出了": [], "卡在": [], "等主人定": [], "数": {}, "出处": []}
    for k, v in (zuole or {}).items():
        d["做了"][k] = d["做了"].get(k, 0) + v
    for key, xs in (("出了", chule), ("卡在", kazai), ("等主人定", deng)):
        for x in xs:
            if x and x not in d[key]:
                d[key].append(x)
    d["数"].update(shu or {})
    if chuchu and chuchu not in d["出处"]:
        d["出处"].append(chuchu)
    d["记录时间"] = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    tmp.replace(p)
    return p


def main(argv=None):
    a = argparse.ArgumentParser()
    a.add_argument("--店铺", required=True); a.add_argument("--成员", required=True); a.add_argument("--做了", nargs="*", default=[])
    a.add_argument("--出了", nargs="*", default=[]); a.add_argument("--卡在", nargs="*", default=[]); a.add_argument("--等主人定", nargs="*", default=[])
    a.add_argument("--出处", default=""); a.add_argument("--今天")
    a = a.parse_args(argv)
    zuole = {k: float(v) if "." in v else int(v) for k, v in (x.split("=", 1) for x in a.做了 if "=" in x)}
    print("回执已记", ji(a.店铺, a.成员, zuole, a.出了, a.卡在, a.等主人定, None, a.出处, a.今天))


if __name__ == "__main__":
    main()

files.底子.py:
"""掌柜各脚本共用的小工具：家目录、店铺文件夹（四位共用的店铺根目录）、参数（决策库盖默认值）、卡片开头段、夹带检查、出表。
别的脚本这样引：import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent / "keep-base")); import 底子"""
import json, os, pathlib, re

HOME = pathlib.Path(os.environ.get("KEEP_HOME", pathlib.Path.home() / ".yunjian" / "keep"))
KU = HOME / "库"
if not KU.exists() and (pathlib.Path(__file__).resolve().parents[2] / "库").exists():
    KU = pathlib.Path(__file__).resolve().parents[2] / "库"   # 还没装到 ~/.yunjian/keep 时用包里自带的库（实测 10-31：没装就直接报错）


def jintian():
    """今天：环境变量 KEEP_TODAY（测试、演练用，如 2026-11-10）优先，没有用系统日期。"""
    import datetime as _dt
    v = os.environ.get("KEEP_TODAY")
    return _dt.date.fromisoformat(v[:10]) if v else _dt.date.today()


def dianpu_gen():
    """店铺根目录：有四位共用的 ~/.yunjian/店铺/ 就用它（一家店一个文件夹、一份经营决策库、掌柜从这里汇总），没有就用自己的 <HOME>/店铺/（只装这一位时）。"""
    g = HOME.parent / "店铺"
    return g if g.is_dir() else HOME / "店铺"


def dianpu(ming=None):
    """店铺文件夹：给了店名就是 店铺/<店名>，给的是路径（带 / 或 ~）照路径；没给就用 店铺/ 下唯一的一家（不止一家要主人说是哪家）。
    Bot 实测 10-31：「--店铺 阿青卫衣」被当成相对路径，卡写进了技能目录。"""
    d = dianpu_gen()
    if ming:
        m = str(ming)
        return pathlib.Path(m).expanduser() if ("/" in m or m.startswith("~")) else d / m
    xs = [p for p in d.iterdir() if p.is_dir()] if d.exists() else []
    if len(xs) != 1:
        raise SystemExit(f"不知道是哪家店：{d} 下有 {len(xs)} 家，用 --店铺 指定")
    return xs[0]


def kaitou(p):
    """读卡片开头 --- 之间的「键: 值」（一层，参数下面缩进的两格也读进「参数」）。"""
    t = pathlib.Path(p).read_text(encoding="utf-8")
    m = re.match(r"---\n(.*?)\n---", t, re.S)
    out, cs = {}, None
    for line in (m.group(1).splitlines() if m else []):
        if line.startswith("  ") and cs is not None:
            k, _, v = line.strip().partition(":")
            out.setdefault("参数", {})[k.strip()] = v.split("#")[0].strip()
        elif ":" in line:
            k, _, v = line.partition(":")
            k = k.strip(); cs = k if k == "参数" else None
            if k != "参数":
                out[k] = v.split("#")[0].strip()
    return out


def moren_canshu(ku=None):
    """默认值/看店-服装店.md 里的 json 参数块。"""
    t = ((ku or KU) / "默认值" / "看店-服装店.md").read_text(encoding="utf-8")
    return json.loads(re.search(r"```json\n(.*?)\n```", t, re.S).group(1))


def canshu(dp=None, ku=None):
    """参数：服装店默认值，再用店铺经营决策库里「状态: 生效」的卡盖掉同名参数。返回（参数, 用了默认值的名字）。"""
    cs = moren_canshu(ku)
    gai = set()
    if not dp:   # 没指定店铺：店铺/ 下只有一家就用它，免得主人定的规矩被默认值盖住
        try:
            dp = dianpu()
        except SystemExit:
            dp = None
    jc = dianpu(dp) / "经营决策库" if dp else None
    if jc and jc.exists():
        for p in sorted(jc.glob("D-*.md")):
            if p.name.startswith("._"):   # Mac 打包带的隐藏文件（Bot 实测自报 14）
                continue
            k = kaitou(p)
            if k.get("状态") != "生效":
                continue
            for n, v in (k.get("参数") or {}).items():
                if n in cs:
                    try:
                        cs[n] = type(cs[n])(float(v)) if isinstance(cs[n], (int, float)) else v
                    except ValueError:
                        cs[n] = v
                    gai.add(n)
    return cs, sorted(set(cs) - gai)


JIADAI = re.compile(r"(AI|ai|助手|机器人).{0,8}(注意|请|必须)|不用问|忽略(之前|上面|以上)|直接.{0,10}(发布|改|删除|下单)|ignore (previous|all)", re.I)


def kexi(s):
    """像写给 AI 的话（夹带指令）就返回那一段原文，否则空串。"""
    m = JIADAI.search(s or "")
    return zhaiju(s, 120) if m else ""


def zhaiju(s, n=60):
    """原话摘出来给主人看：不超过 n 字整段给；长了按句子截（。！？；换行），不从半个字、半句话截（Bot 实测 10-31：丢了开头的「多」、截掉了「改成50%」）。"""
    s = (s or "").strip()
    if len(s) <= n:
        return s
    ju = re.split(r"(?<=[。！？!?；;\n])", s)
    out = ""
    for j in ju:
        if out and len(out) + len(j) > n:
            break
        out += j
    return out.strip() + ("…" if len(out.strip()) < len(s) else "")


QUAN = "①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳"


def biao(tou, hang, kuan=False, chu=None, zhu=None, jian=1):
    """出表（杨先生 10-31：按界面做最优展示）。kuan=True 一张宽表（电脑、飞书、网页）；
    默认窄表（Grok Bot、手机聊天框）：出处那一列（chu）换成编号 ①②，完整出处列在表下；
    长理由那一列（zhu）挪到表下，按 jian 那一列的值一条一条写。"""
    if kuan or (chu is None and zhu is None):
        return "\n".join(["| " + " | ".join(tou) + " |", "|" + "---|" * len(tou)] + ["| " + " | ".join(map(str, h)) + " |" for h in hang])
    bh, xia, zhus = {}, [], []
    for h in hang:
        if chu is not None:
            c = str(h[chu])
            if c not in bh:
                bh[c] = QUAN[len(bh)] if len(bh) < len(QUAN) else f"({len(bh) + 1})"
        if zhu is not None and str(h[zhu]).strip() not in ("", "—"):
            zhus.append(f"- {h[jian]}：{h[zhu]}")
    keep = [i for i in range(len(tou)) if i != zhu]
    t2 = [("出处" if i == chu else tou[i]) for i in keep]
    rows = [[(bh[str(h[i])] if i == chu else str(h[i])) for i in keep] for h in hang]
    out = ["| " + " | ".join(t2) + " |", "|" + "---|" * len(t2)] + ["| " + " | ".join(r) + " |" for r in rows]
    if zhus:
        out += ["", "说明：", *zhus]
    if bh:
        out += ["", "出处：", *[f"{v} {k}" for k, v in bh.items()]]
    return "\n".join(out)


def dianpus():
    """店铺根目录下所有店（一家店一个文件夹；以「.」「_」开头的不算）。"""
    g = dianpu_gen()
    return sorted(p for p in g.iterdir() if p.is_dir() and not p.name.startswith((".", "_"))) if g.is_dir() else []


def yuan(x):
    """金额：整数加千分位，带小数的保留 0 位（报里看个大数）。"""
    return "—" if x is None else f"{x:,.0f}"


def bili(x, fuhao=True):
    """比例 0.1234 → +12%；None → —。"""
    if x is None:
        return "—"
    return (f"{x:+.0%}" if fuhao else f"{x:.0%}").replace("-", "−")


PIN = ("弯刀裤", "卫裤", "卫衣", "打底衫", "开衫", "外套", "T恤", "衬衫", "毛衣", "针织衫", "连衣裙", "半身裙", "牛仔裤", "阔腿裤", "裤", "裙", "衫")


def duanming(s, n=10):
    """商品名太长，报里用短名：【款名】＋品类（如「斑点狗·卫衣」）；带「运补」的标出来。认不出就截前 n 个字。"""
    s = s or ""
    m = re.findall(r"【([^】]+)】", s)
    kuan = next((x for x in m if "运补" not in x and len(x) <= 8), "")
    lei = next((p for p in PIN if p in s), "")
    jian = "·".join(x for x in (kuan, lei) if x) or s[:n]
    return jian + ("（运补）" if "运补" in s and "运补" not in jian else "")


DAIMA = [(re.compile(r"(?<![\d])1[3-9]\d(?:[\s/\-—.]?\d){8}(?![\d])"), "1**********"),
         (re.compile(r"(?<![\d])\d{3,4}[/\-—\s]\d{3,4}[/\-—\s]\d{3,4}(?![\d])"), "***（号码已打码）"),
         (re.compile(r"(微信|vx|VX|wx|WX|V信|薇信)\s*[:：号]?\s*[A-Za-z0-9_\-]{5,}"), r"\1***")]


def daima(s):
    """推送前把手机号、微信号打码（达人消息原话里常带；全员规范：联系方式不进推送）。"""
    for pat, rep in DAIMA:
        s = pat.sub(rep, s or "")
    return s

files.指纹.py:
"""算官方页面正文指纹：去掉导航和页尾，只留「更新时间」到「这篇文章是否对你有帮助」之间的正文，压掉空白后取 sha256 前 12 位。
用法：python3 指纹.py <取回的正文.txt>      巡检.py 也用它；指纹变了就是正文改了。"""
import hashlib, re, sys

def zhengwen(t):
    k = t.find('----正文----')          # 取原文.mjs 存的正文文件：只认分隔线以后的正文
    if k >= 0:
        return re.sub(r'\s+', '', t[k + len('----正文----'):])
    i = t.find('更新时间')
    t = t[i:] if i >= 0 else t
    j = t.find('这篇文章是否对你有帮助')
    t = t[:j] if j >= 0 else t
    t = re.sub(r'阅读量[:：]\s*\d+', '', t)
    return re.sub(r'\s+', '', t)

def zhiwen(t):
    return hashlib.sha256(zhengwen(t).encode()).hexdigest()[:12]

if __name__ == '__main__':
    for p in sys.argv[1:]:
        print(zhiwen(open(p, encoding='utf-8').read()), p)

files.汇总.py:
"""掌柜 · 汇总：一家店某个时段的「快照」——后台数（掌柜自己读的）＋三位员工的回执＋店里规矩 → 业绩、预估利润、店铺分变化、排行、达人、员工、要您管的。
出报.py、提醒.py、员工看板.py 都从这里拿数；数全有出处，缺什么写「没取到」，不估不编。只用标准库。"""
import datetime as dt, json, pathlib, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); import 底子

YUANGONG = {"abacus": "算盘", "hawk": "货郎", "brok": "经纪"}
HUIZHI_BIXU = ["成员", "店铺", "日期", "做了", "出了", "卡在", "等主人定", "数"]


def du_houtai(dp, day, zhi=None, yao="实时"):
    """这家店这天最新一份「有 yao 这块」的后台数（掌柜/后台/<日期>/<时刻>/后台数.json）；给了 zhi（如 "1150"）只看这个时刻以前的。
    出报要「实时」（每小时看消息那次只读体验分和消息，不能拿来出报），提醒要「合作消息」。"""
    d = pathlib.Path(dp) / "掌柜" / "后台" / str(day)
    if not d.is_dir():
        return None
    for p in sorted((p for p in d.iterdir() if p.is_dir() and (p / "后台数.json").exists() and (zhi is None or p.name <= zhi)), reverse=True):
        ht = json.loads((p / "后台数.json").read_text(encoding="utf-8"))
        if not yao or ht.get(yao):
            return ht
    return None


def du_huizhi(dp, day):
    """三位员工这天的回执；格式不对的标「回执格式不对」，不猜（格式见 库/回执格式.json）。"""
    out = {}
    d = pathlib.Path(dp) / "回执" / str(day)
    for k in YUANGONG:
        p = d / f"{k}.json"
        if not p.exists():
            out[k] = None
            continue
        try:
            h = json.loads(p.read_text(encoding="utf-8"))
            que = [x for x in HUIZHI_BIXU if x not in h]
            out[k] = h if not que else {"_坏": f"回执格式不对（缺 {'、'.join(que)}）"}
        except ValueError:
            out[k] = {"_坏": "回执格式不对（不是 JSON）"}
    return out


def yunfei(dp, cs):
    """每单运费：店里经营决策卡写了「默认仓」和「<仓>_每单」，或算盘写的「快递单价」，就用它；否则用参数「运费_每单」（联调 10-31：算盘的卡掌柜也认）。"""
    jc = pathlib.Path(dp) / "经营决策库"
    for p in sorted(jc.glob("D-*.md")) if jc.is_dir() else []:
        k = 底子.kaitou(p)
        if k.get("状态", "").startswith("生效"):
            can = k.get("参数") or {}
            cang = can.get("默认仓")
            if cang and f"{cang}_每单" in can:
                try:
                    return float(can[f"{cang}_每单"]), f"店里快递单价（{k.get('编号')}）"
                except ValueError:
                    pass
            if "快递单价" in can:
                try:
                    return float(can["快递单价"]), f"店里快递单价（{k.get('编号')}，算盘的卡）"
                except ValueError:
                    pass
    v = float(cs.get("运费_每单") or 0)
    return (v, "参数 运费_每单") if v else (None, "")


def yugu(ss, cs, yf):
    """当天预估利润（粗算）：成交 − 退款（支付时间）− 成本 − 达人佣金 − 平台佣金 − 运费。缺成本规矩或运费就不算，写明缺什么。"""
    g = lambda k: (ss.get(k) or {}).get("值")
    cj, tk, dd = g("成交金额"), g("退款金额_支付时间") or 0, g("成交订单数")
    zb = float(cs.get("成本_占定价") or 0)
    que = [x for x, ok in (("成交金额", cj is not None), ("成本规矩（成本占定价）", zb > 0), ("每单运费", yf[0] is not None), ("订单数", dd is not None)) if not ok]
    if que:
        return None, "预估利润没算：缺" + "、".join(que)
    jing = cj - tk
    dr = g("达人佣金_预估")
    drs = "后台预估口径"
    if dr is None:
        dr = (g("达人成交金额") or jing * float(cs.get("达人带货占比") or 0)) * float(cs.get("默认佣金") or 0)
        drs = "按默认佣金估"
    pt = g("平台佣金_预估")
    pts = "后台预估口径"
    if pt is None:
        pt = cj * float(cs.get("平台服务费率") or 0)
        pts = f"按 {float(cs.get('平台服务费率') or 0):.0%} 估"
    lr = jing * (1 - zb) - dr - pt - dd * yf[0]
    return lr, (f"成交 {cj:,.0f} − 退款 {tk:,.0f}（支付时间）− 成本（定价×{zb:g}）− 达人佣金 {dr:,.0f}（{drs}）"
                f"− 平台佣金 {pt:,.0f}（{pts}）− 运费 {dd:.0f} 单×{yf[0]:g}（{yf[1]}）；退货运费没算，以算盘结算为准")


def tiyan(dp, ty, xie=True):
    """店铺分变化：和自己存的上一次「更新时间不同」的记录比（体验分每天约 22 点更新一次）。返回 (总分变化, 各分项变化, 上次)。"""
    p = pathlib.Path(dp) / "掌柜" / "体验分记录.json"
    try:
        jl = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        jl = {}
    gx, zf = ty.get("更新时间"), ty.get("总分")
    if not gx or zf is None:
        return None, {}, None
    qian = [k for k in sorted(jl) if k < gx]
    bh, fx, shang = None, {}, None
    if qian:
        shang = jl[qian[-1]]
        bh = zf - shang["总分"]
        for k, v in (ty.get("分项") or {}).items():
            if k in (shang.get("分项") or {}):
                fx[k] = v["分"] - shang["分项"][k]
    elif ty.get("较前1日") is not None:   # 第一次跑，没有自己的记录：用页面给的较前1日
        bh = ty["较前1日"]
        fx = {k: v.get("较前1日") for k, v in (ty.get("分项") or {}).items() if v.get("较前1日") is not None}
    if xie and gx not in jl:
        jl[gx] = {"总分": zf, "分项": {k: v["分"] for k, v in (ty.get("分项") or {}).items()}}
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(jl, ensure_ascii=False, indent=1), encoding="utf-8")
    return bh, fx, shang


def yuangong(hz):
    """员工看板：一位一行——今天做了／出了什么／卡在哪、等您定。"""
    rows = []
    for k, zh in YUANGONG.items():
        h = hz.get(k)
        if h is None:
            rows.append([zh, "今天没跑（没有回执）", "—", "—"])
        elif "_坏" in h:
            rows.append([zh, h["_坏"], "—", "—"])
        else:
            zuo = "、".join(f"{a} {b:g}" for a, b in h["做了"].items()) or "—"
            chu = "、".join(h["出了"][:3]) + ("等" if len(h["出了"]) > 3 else "") or "—"
            ks = [f"等您定：{x}" for x in h["等主人定"]] + h["卡在"]   # 等主人定排前面，卡在多了也挤不掉（联调 Bot 自报 10-31）
            ka = "；".join(ks[:3]) + (f"；另 {len(ks) - 3} 条" if len(ks) > 3 else "") or "—"
            rows.append([zh, zuo, chu, ka])
    return rows


def kuaizhao(dp, day, shiduan="现在", zhi=None, xie=True):
    """一家店的快照，写进 掌柜/快照/<日期>-<时段>.json（xie=False 只算不写，演练用）。"""
    dp = pathlib.Path(dp)
    cs, mo = 底子.canshu(dp)
    ht = du_houtai(dp, day, zhi) or {}
    hz = du_huizhi(dp, day)
    ss = ht.get("实时") or {}
    yf = yunfei(dp, cs)
    lr, lrs = yugu(ss, cs, yf) if ss else (None, "后台没取到")
    ty = ht.get("体验分") or {}
    bh, fx, _ = tiyan(dp, ty, xie) if ty.get("总分") is not None else (None, {}, None)
    g = lambda k: (ss.get(k) or {}).get("值")
    dr_zb = (g("达人成交金额") / g("成交金额")) if g("达人成交金额") and g("成交金额") else None
    yao = []
    if bh is not None and bh <= -float(cs["掉分即时线"]):
        yao.append(("即时", f"店铺分掉 {abs(bh):g} 分" + (f"（{min(fx, key=fx.get)}）" if fx else ""), "体验分"))
    elif bh is not None and bh <= -float(cs["掉分进报线"]):
        yao.append(("今天", f"店铺分掉 {abs(bh):g} 分" + (f"（{min(fx, key=fx.get)}）" if fx else ""), "体验分"))
    jz = (ss.get("成交金额") or {}).get("较昨日")
    if jz is not None and jz <= float(cs["业绩掉线"]):
        yao.append(("今天", f"成交比昨天 {底子.bili(jz)}", "实时"))
    for x in ((hz.get("brok") or {}).get("数") or {}).get("今日待办", []):
        if x.get("事") in ("申样快到时限", "转人工", "谈佣金", "申样对不上", "夹带指令", "签收没动静"):
            yao.append(("今天", f"达人 {x.get('达人')} {x.get('事')}", "经纪回执"))
    for k in ("brok", "hawk", "abacus"):
        for x in (hz.get(k) or {}).get("等主人定", []):
            if not any(x in y[1] for y in yao):
                yao.append(("今天", f"{YUANGONG[k]}：{x}", f"{YUANGONG[k]}回执"))
    for x in (((hz.get("hawk") or {}).get("数") or {}).get("快下架") or []):
        yao.append(("本周", f"{底子.duanming(x)} 快被自动下架", "货郎回执"))
    dai = ht.get("待办") or {}
    if dai.get("待处理违规"):
        yao.append(("今天", f"后台有 {dai['待处理违规']} 条待处理违规（抖店首页顶部待办点「待处理违规」进去看；申诉、整改由您办，掌柜后台只看不改）", "首页待办"))
    snap = {"店铺": dp.name, "日期": str(day), "时段": shiduan, "记录时间": ht.get("记录时间"),
            "实时": ss, "达人占比": dr_zb, "预估利润": lr, "利润说明": lrs,
            "体验分": {"总分": ty.get("总分"), "变化": bh, "分项变化": fx, "分项": {k: v.get("分") for k, v in (ty.get("分项") or {}).items()},
                    "短板": ty.get("短板"), "保障": ty.get("保障"), "更新时间": ty.get("更新时间"), "今日已更新": ty.get("今日已更新")},
            "报退款率": int(cs["报退款率"]),
            "商品榜": [dict(r, 短名=底子.duanming(r["商品"])) for r in (ht.get("商品榜") or [])[: int(cs["报里每张表最多行"])]],
            "待办": dai, "联盟": ht.get("联盟") or {}, "载体": ht.get("载体") or {},
            "员工": yuangong(hz), "回执": {k: (v if v and "_坏" not in v else None) for k, v in hz.items()},
            "要管": [{"级": a, "事": b, "出处": c} for a, b, c in yao],
            "没取到": (ht.get("没取到") or []) if ht else ["后台数没取到（这个时段没读到后台）"],
            "出处": ht.get("出处") or {}, "用了默认值": [x for x in mo if x in ("成本_占定价", "运费_每单")]}
    if xie:
        p = dp / "掌柜" / "快照" / f"{day}-{shiduan}.json"
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(snap, ensure_ascii=False, indent=1), encoding="utf-8")
    return snap

files.统一店铺.py:
"""掌柜 · 统一店铺：把算盘、货郎、经纪各自的店铺文件夹并进四位共用的 ~/.yunjian/店铺/<店名>/（一家店一个名字、一份经营决策库），只挪不删。
用法：python3 统一店铺.py [--改名 旧名=新名 …] [--只并 abacus,hawk,brok] [--演练]
  例：python3 统一店铺.py --改名 阿青卫衣=抖店-A 实测店=抖店-A --演练   先看计划，没问题去掉 --演练
做法：每位成员 <家目录>/店铺/<旧名>/ 里的东西挪进 店铺/<新名>/；同名文件内容一样就留一份，不一样的把挪进来的改名「原名-来自<成员>」；
经营决策库的卡编号撞了（不同内容同编号）→ 挪进来的那张改成同类下一个空号，卡里「编号」跟着改；每一步记进 经营决策库/变更记录.md。
挪完，旧文件夹剩下的（应该是空的）整个挪到 <家目录>/店铺-已并入-<日期>/ 留底。之后三位成员会自动用共用的根目录（底子 dianpu_gen）。"""
import argparse, datetime as dt, filecmp, pathlib, re, shutil, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); import 底子

CHENG = {"abacus": "算盘", "hawk": "货郎", "brok": "经纪"}


def xia_hao(jc, lei):
    ns = [int(m.group(1)) for p in jc.glob(f"D-{lei}-*.md") if (m := re.match(rf"D-{lei}-(\d+)", p.name))]
    return max(ns, default=0) + 1


def bing_juece(src, dst, cheng, ji, yanlian):
    """挪经营决策卡：同一张卡的几个版本（同编号）一起走；只有和「别的成员先放进来的」同编号、内容又不同才改号，几个版本改成同一个新号。"""
    dst.mkdir(parents=True, exist_ok=True)
    yuan = {p.name for p in dst.glob("D-*.md")}
    zu = {}
    for p in sorted(src.glob("*")):
        if p.name.startswith("._"):
            continue
        if p.name == "变更记录.md":
            q = dst / p.name
            if q.exists():
                q.write_text(q.read_text(encoding="utf-8").rstrip("\n") + "\n" + "\n".join(
                    l for l in p.read_text(encoding="utf-8").splitlines() if l.startswith("| 20")) + "\n", encoding="utf-8")
                p.unlink()
            else:
                shutil.move(str(p), q)
            continue
        m = re.match(r"D-([A-Z]+)-(\d+)", p.name)
        zu.setdefault(m.group(0) if m else p.name, []).append(p)
    for bh, ps in zu.items():
        m = re.match(r"D-([A-Z]+)-(\d+)$", bh)
        zhuang = [y for y in yuan if m and y.startswith(bh + "-")]
        if zhuang and all(any((dst / y).exists() and filecmp.cmp(p, dst / y, shallow=False) for y in zhuang) for p in ps):
            ji.append(f"{cheng} {bh}：和已有的一样，留一份")
            for p in ps:
                p.unlink()
            continue
        xin = bh
        if zhuang:
            xin = f"D-{m.group(1)}-{xia_hao(dst, m.group(1)):03d}"
            ji.append(f"{cheng} {bh}（{ps[0].name[len(bh) + 1:-3]}）：编号和别的成员的撞了 → 改成 {xin}")
        else:
            ji.append(f"{cheng} {bh}：挪进来" + (f"（{len(ps)} 个版本）" if len(ps) > 1 else ""))
        for p in ps:
            q = dst / (xin + p.name[len(bh):])
            if xin != bh:
                q.write_text(p.read_text(encoding="utf-8").replace(f"编号: {bh}", f"编号: {xin}", 1), encoding="utf-8"); p.unlink()
            else:
                shutil.move(str(p), q)


def main(argv=None):
    a = argparse.ArgumentParser(); a.add_argument("--改名", nargs="*", default=[]); a.add_argument("--只并", default="abacus,hawk,brok")
    a.add_argument("--演练", action="store_true")
    a = a.parse_args(argv)
    gai = dict(x.split("=", 1) for x in a.改名 if "=" in x)
    root = 底子.HOME.parent
    if a.演练:   # 演练：把要并的几个文件夹复制到临时目录，在那里真跑一遍，计划和真做一模一样，原处一点不动
        import tempfile
        tmp = pathlib.Path(tempfile.mkdtemp(prefix="统一店铺演练-"))
        for c in a.只并.split(",") + ["店铺"]:
            src = root / c / "店铺" if c != "店铺" else root / "店铺"
            if src.is_dir():
                shutil.copytree(src, (tmp / c / "店铺") if c != "店铺" else tmp / "店铺")
        root = tmp
    gen = root / "店铺"
    ji, today = [], dt.date.today().isoformat()
    for cheng in a.只并.split(","):
        home = root / cheng
        old = home / "店铺"
        ds = sorted(x for x in old.iterdir() if x.is_dir() and not x.name.startswith(".")) if old.is_dir() else []
        if not ds:   # 没有店（文件夹不在或是空的）：不并、不留底（Bot 实测 10-31）
            continue
        for d in ds:
            xin = gai.get(d.name, d.name)
            dst = gen / xin
            ji.append(f"— {CHENG.get(cheng, cheng)}：{d} → {dst}")
            if True:
                dst.mkdir(parents=True, exist_ok=True)
            for p in sorted(d.iterdir()):
                if p.name.startswith("._"):
                    continue
                q = dst / p.name
                if p.name == "经营决策库" and p.is_dir():
                    bing_juece(p, q, CHENG.get(cheng, cheng), ji, False)
                    continue
                if not q.exists():
                    ji.append(f"{CHENG.get(cheng, cheng)} {p.name}：挪进来")
                    if True:
                        shutil.move(str(p), q)
                elif p.is_file() and q.is_file() and filecmp.cmp(p, q, shallow=False):
                    ji.append(f"{CHENG.get(cheng, cheng)} {p.name}：和已有的一样，留一份")
                    if True:
                        p.unlink()
                else:
                    alt = dst / f"{p.stem}-来自{CHENG.get(cheng, cheng)}{p.suffix}"
                    ji.append(f"{CHENG.get(cheng, cheng)} {p.name}：已有同名、内容不同 → 存成 {alt.name}")
                    if True:
                        shutil.move(str(p), alt)
        if True:
            bak = home / f"店铺-已并入-{today}"
            shutil.move(str(old), bak)
            ji.append(f"{CHENG.get(cheng, cheng)} 旧文件夹剩下的挪到 {bak}（留底，不删）")
    if not ji:
        print("没有要并的：三位的家目录里都没有店铺文件夹"); return
    print(("【演练：在临时目录里照做了一遍，原处什么都没动】\n" if a.演练 else "") + "\n".join(ji).replace(str(root), "~/.yunjian" if a.演练 else str(root)))
    if not a.演练:
        for dst in (gen.iterdir() if gen.is_dir() else []):
            jc = dst / "经营决策库"
            if jc.is_dir():
                b = jc / "变更记录.md"
                head = "" if b.exists() else "# 经营决策库 · 变更记录（只追加，不删）\n| 日期 | 卡 | 版本 | 改了什么 | 出处 | 谁定的 |\n|---|---|---|---|---|---|\n"
                b.write_text((b.read_text(encoding="utf-8") if b.exists() else head).rstrip("\n") + f"\n| {today} | 全部 | — | 掌柜统一店铺：三位的店铺文件夹并成这一份（撞号的改了号，见下） | 统一店铺.py | 主人点头 |\n"
                             + "".join(f"| {today} | — | — | {x} | 统一店铺.py | 主人点头 |\n" for x in ji if "改成" in x), encoding="utf-8")


if __name__ == "__main__":
    main()

files.读页面.py:
"""掌柜 · 读页面：把存下来的后台页面文字（首页、商家体验分、合作消息）变成一份 后台数.json（格式见 库/模板/后台数格式.json）。
用法：python3 读页面.py <文件夹> --店铺 <店铺文件夹名，如 抖店-A> [--后台店名 <后台右上显示的店名>] [--记录时间 "2026-11-10 11:48"] [--出 <后台数.json>]
后台店名不给：读店铺文件夹里 掌柜/店铺档案.json 的「后台店名」；档案里还没有就把这次看到的记下来（第一次），以后对不上整份作废。
文件夹里放：首页.txt＋首页-涨跌.json、体验分.txt＋体验分-涨跌.json、合作消息.json（可选，[{"达人","最后一句","时间"}]）。
涨跌.json 是页面上「较昨日／较前1日」箭头的方向，按页面顺序：[{"值": "43.94%", "方向": "down"}]（路线卡 M-KP-001、M-KP-002）。
页面文字里只有百分比、没有正负号，方向只认涨跌.json；对不上就写 null，不猜。缺哪个文件，那块进「没取到」。"""
import argparse, json, pathlib, re, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); import 底子

NUM = re.compile(r"^[¥￥]?\s*(-?[\d,]+(?:\.\d+)?)\s*(万)?$")
PCT = re.compile(r"^(-?[\d.]+)\s*%$")


def shu(s):
    m = NUM.match((s or "").strip())
    if not m:
        return None
    v = float(m.group(1).replace(",", ""))
    return v * 10000 if m.group(2) else v


class Qushi:
    """按页面顺序消费涨跌箭头：值对得上才用，方向 up→正、down→负，没有箭头（持平）→0。"""
    def __init__(self, xs):
        self.xs, self.yong = list(xs or []), set()

    def na(self, zhi):
        for j, x in enumerate(self.xs):
            v = str(x.get("值", "")).strip()
            if j not in self.yong and (v == zhi or v.endswith(zhi)):
                self.yong.add(j)
                return {"up": 1, "down": -1}.get(x.get("方向", ""), 0)
        return None


def jiao(lines, i, qs, biaoqian="较昨日", chang=12):
    """从第 i 行往后找「较昨日」后面的百分比或持平，返回带符号小数；找不到 None。"""
    for k in range(i, min(i + chang, len(lines))):
        if lines[k].startswith(biaoqian):
            nxt = lines[k + 1].strip() if k + 1 < len(lines) else ""
            if nxt == "持平":
                return 0.0
            m = PCT.match(nxt) or re.match(r"^(-?[\d.]+)$", nxt)
            if not m:
                return None
            fx = qs.na(nxt)
            if fx is None:
                return None
            v = float(m.group(1))
            return fx * (v / 100 if nxt.endswith("%") else v)
    return None


def zhi_hou(lines, i, chang=6, tiao=("¥", "￥", "构成", "支付时间", "退款时间", "退款时…", "支付时…", "分")):
    for k in range(i + 1, min(i + 1 + chang, len(lines))):
        t = lines[k].strip()
        if t in tiao or not t:
            continue
        v = shu(t)
        if v is not None:
            return v, k
        return None, k
    return None, i


