            continue
        zr = None
        if k < len(L) and L[k] == "昨日":
            zr, _ = zhi_lianxu(L, k + 1)
        out[key] = {"值": v, "昨日": zr, "较昨日": (v / zr - 1) if zr else None}
    m = re.search(r"退款率（支付时间）\s*([\d.]+)%\s*昨日\s*([\d.]+)\s*%", " ".join(L))
