    return rows


SHIJIAN = re.compile(r"^(\d{1,2}:\d{2}|昨天|前天|星期[一二三四五六日天]|\d{1,2}/\d{1,2}|\d{4}-\d{2}-\d{2})$")


def du_xiaoxi(t):
    """合作消息页左栏：「达人昵称｜最后一句｜时间」三个一组（M-BY-003 第 3 步）；顶上读 7 日回复率、建联额度。"""
